<script setup lang="ts">
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount} from 'vue';
import {message,Modal} from 'ant-design-vue';
import MarkdownIt from 'markdown-it';
import DOMPurify from 'dompurify';
import {onBeforeRouteLeave} from 'vue-router';
import {support,type HelpCategory,type HelpArticle,type HelpDraft,type SupportPage} from '../api/modules/support';
import {useAuthStore} from '../stores/auth';
const auth=useAuthStore();const categories=ref<HelpCategory[]>([]),rows=ref<HelpArticle[]>([]),current=ref<HelpArticle|null>(null),open=ref(false),busy=ref(false),error=ref(''),versions=ref<unknown[]>([]);
const empty=():HelpDraft=>({title:'',summary:'',body:'',keywords:'',pinned:false,sort:0,language:'zh-Hans',min_version:'',max_version:''});
const form=ref<HelpDraft>(empty()),category=ref(''),categoryCode=ref(''),categoryName=ref(''),categoryActive=ref(true),categorySort=ref(0),cursor=ref<string|null>(null);let token=0;const saved=ref('');const uploading=ref(false);const imageInput=ref<HTMLInputElement|null>(null);
const imageURLs=reactive<Record<string,string>>({});const markdown=new MarkdownIt({html:false,linkify:false});
markdown.renderer.rules.image=(tokens,index)=>{const t=tokens[index]!;const source=t.attrGet('src')??'';const id=source.replace('support-image:','');const url=imageURLs[id];return url?`<img src="${markdown.utils.escapeHtml(url)}" alt="${markdown.utils.escapeHtml(t.content)}" style="max-width:100%" />`:'<span>帮助图片加载中</span>';};
const previewHTML=computed(()=>DOMPurify.sanitize(markdown.render(form.value.body)));
watch(()=>form.value.body,async(value)=>{const stamp=token;for(const match of value.matchAll(/support-image:([0-9a-fA-F-]{36})/g)){const id=match[1]!;if(imageURLs[id])continue;try{const r=await support.get<{url:string}>(`help/images/${id}/url/`);const u=new URL(r.url);if(stamp===token&&u.protocol==='https:'&&u.hostname.endsWith('.aliyuncs.com'))imageURLs[id]=u.href;}catch{/* invalid or not uploaded assets cannot be published */}}});
onBeforeRouteLeave(()=>!open.value||snapshot()===saved.value||window.confirm('放弃尚未保存的帮助草稿？'));
const snapshot=()=>JSON.stringify([form.value,category.value]);
async function load(more=false){busy.value=true;error.value='';try{const [c,a]=await Promise.all([support.get<HelpCategory[]>('help/categories/'),support.get<SupportPage<HelpArticle>>('help/articles/',{cursor:more?cursor.value:'',limit:50})]);categories.value=c;rows.value=more?[...rows.value,...a.results]:a.results;cursor.value=a.next_cursor;}catch(e){error.value=String(e);}finally{busy.value=false;}}
function edit(a:HelpArticle|null){if(open.value&&snapshot()!==saved.value&&!window.confirm('放弃尚未保存的帮助草稿？'))return;token++;current.value=a;category.value=a?.category??categories.value[0]?.code??'';form.value=a?{...a.draft}:empty();versions.value=[];open.value=true;saved.value=snapshot();}
function close(){if(busy.value||uploading.value)return;if(snapshot()!==saved.value&&!window.confirm('放弃尚未保存的草稿？'))return;open.value=false;token++;}
async function save(){busy.value=true;error.value='';try{const payload={...form.value,category:category.value,revision:current.value?.revision};const a=current.value?await support.patch<HelpArticle>(`help/articles/${current.value.id}/`,payload):await support.post<HelpArticle>('help/articles/',payload);current.value=a;saved.value=snapshot();message.success('草稿已保存，需发布后用户才能看到');await load();}catch(e){error.value=String(e);}finally{busy.value=false;}}
function publish(action:string){if(!current.value)return;if(snapshot()!==saved.value){message.warning('请先保存当前草稿');return;}const a=current.value;Modal.confirm({title:action==='publish'?'发布此帮助文章？':'下线此帮助文章？',content:action==='publish'?'已保存草稿将替换公开版本。':'用户将无法继续在线访问该文章。',onOk:async()=>{try{current.value=await support.post<HelpArticle>(`help/articles/${a.id}/${action}/`,{revision:a.revision});await load();message.success('操作成功');}catch(e){error.value=String(e);}}});}
async function history(){const a=current.value,t=token;if(!a)return;try{const p=await support.get<SupportPage<unknown>>(`help/articles/${a.id}/versions/`,{limit:50});if(t===token)versions.value=p.results;}catch(e){error.value=String(e);}}
async function uploadImage(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const stamp=token;uploading.value=true;try{if(file.size>10_000_000||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('仅支持不超过 10 MB 的 JPEG、PNG、WebP');const r=await support.post<{id:string;put_url:string;put_headers:Record<string,string>}>('help/images/',{mime:file.type,size:file.size});const url=new URL(r.put_url);if(url.protocol!=='https:'||!url.hostname.endsWith('.aliyuncs.com'))throw Error('图片上传地址无效');const headers={...r.put_headers};delete headers['Content-Length'];const response=await fetch(url,{method:'PUT',headers,body:file});if(!response.ok)throw Error('图片上传失败');await support.post(`help/images/${r.id}/complete/`,{});if(stamp===token){form.value.body+=`\n\n![帮助示意图](support-image:${r.id})\n`;message.success('图片已插入草稿，发布后用户可见');}}catch(e){if(stamp===token)error.value=String(e);}finally{uploading.value=false;(event.target as HTMLInputElement).value='';}}
async function saveCategory(){try{await support.post('help/categories/',{code:categoryCode.value,name:categoryName.value,active:categoryActive.value,sort:categorySort.value});await load();message.success('分类已保存');}catch(e){error.value=String(e);}}
function selectCategory(c:HelpCategory){categoryCode.value=c.code;categoryName.value=c.name;categoryActive.value=c.active;categorySort.value=c.sort;}
onMounted(()=>load());onBeforeUnmount(()=>token++);
</script>
<template><div style="padding:24px"><h2>帮助内容</h2><a-alert v-if="error" type="error" :message="error" show-icon/><a-card title="分类管理" style="margin:16px 0"><a-space wrap><a-button v-for="c in categories" :key="c.code" @click="selectCategory(c)">{{c.name}}{{c.active?'':'（停用）'}}</a-button></a-space><a-space wrap style="margin-top:12px"><a-input v-model:value="categoryCode" placeholder="稳定 code，改名不改 code"/><a-input v-model:value="categoryName" placeholder="分类名称"/><a-input-number v-model:value="categorySort"/><a-switch v-model:checked="categoryActive" checked-children="启用" un-checked-children="停用"/><a-button @click="saveCategory">保存分类</a-button></a-space></a-card>
<a-space><a-button type="primary" @click="edit(null)" :disabled="!categories.length">新增文章</a-button><a-button @click="load()" :loading="busy">刷新</a-button></a-space>
<a-list :data-source="rows" bordered style="margin-top:16px"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="item.draft.title" :description="`${item.category} · ${item.live?'已发布':'未发布 / 已下线'} · 草稿版本 ${item.revision}`"/><a-button @click="edit(item)">编辑 / 预览</a-button></a-list-item></template></a-list><a-button v-if="cursor" @click="load(true)">加载更多</a-button>
<a-drawer :open="open" title="帮助文章草稿" width="min(850px,95vw)" :mask-closable="false" @close="close"><a-alert v-if="error" type="error" :message="error"/><a-form layout="vertical"><a-form-item label="分类"><a-select v-model:value="category"><a-select-option v-for="c in categories" :key="c.code" :value="c.code">{{c.name}}</a-select-option></a-select></a-form-item><a-form-item label="标题"><a-input v-model:value="form.title" :maxlength="120"/></a-form-item><a-form-item label="摘要"><a-input v-model:value="form.summary" :maxlength="300"/></a-form-item><a-form-item label="正文（支持文字排版、HTTPS 链接与帮助图片）"><a-textarea v-model:value="form.body" :rows="12" :maxlength="30000"/></a-form-item><a-form-item label="关键词"><a-input v-model:value="form.keywords"/></a-form-item><a-space wrap><a-checkbox v-model:checked="form.pinned">置顶</a-checkbox><span>排序</span><a-input-number v-model:value="form.sort"/><a-select v-model:value="form.language"><a-select-option value="zh-Hans">简体中文</a-select-option><a-select-option value="en">English</a-select-option></a-select><a-input v-model:value="form.min_version" placeholder="最小应用版本（可空）"/><a-input v-model:value="form.max_version" placeholder="最大应用版本（可空）"/></a-space></a-form>
<a-space><input ref="imageInput" type="file" accept="image/jpeg,image/png,image/webp" style="display:none" @change="uploadImage"/><a-button :loading="uploading" @click="imageInput?.click()">上传并插入帮助图片</a-button><span>图片独立于私人反馈截图</span></a-space><a-divider>草稿预览</a-divider><article class="preview"><h3>{{form.title}}</h3><div v-html="previewHTML"/></article><a-space wrap><a-button type="primary" @click="save" :loading="busy">保存草稿</a-button><a-button v-if="auth.hasPermission('support_center.publish_help')" :disabled="!current||busy" @click="publish('publish')">发布</a-button><a-button v-if="auth.hasPermission('support_center.publish_help')" :disabled="!current?.live||busy" danger @click="publish('unpublish')">下线</a-button><a-button :disabled="!current" @click="history">发布历史</a-button></a-space><pre v-if="versions.length" class="preview">{{JSON.stringify(versions,null,2)}}</pre></a-drawer></div></template>
<style scoped>.preview{white-space:pre-wrap;overflow-wrap:anywhere;padding:16px;background:#f7f8fa;border-radius:10px;margin:16px 0}</style>
